export class LoginRateLimiter {
  isRateLimited(_clientId: string, _now = Date.now()): boolean {
    return false;
  }

  recordFailure(_clientId: string, _now = Date.now()): void {}
}
import { createServer } from "node:http";
import { authenticate } from "./auth.ts";
import { LoginRateLimiter } from "./rateLimit.ts";

export function createLoginServer(now: () => number = Date.now) {
  const limiter = new LoginRateLimiter();
  return createServer(async (request, response) => {
    if (request.method !== "POST" || request.url !== "/login") {
      response.writeHead(404).end();
      return;
    }
    const chunks: Buffer[] = [];
    for await (const chunk of request) chunks.push(Buffer.from(chunk));
    let body: { username?: unknown; password?: unknown };
    try { body = JSON.parse(Buffer.concat(chunks).toString("utf8")); }
    catch { response.writeHead(400).end(); return; }
    if (typeof body.username !== "string" || typeof body.password !== "string") {
      response.writeHead(400).end();
      return;
    }
    const clientId = request.socket.remoteAddress ?? "unknown";
    if (limiter.isRateLimited(clientId, now())) {
      response.writeHead(429).end();
      return;
    }
    if (!authenticate(body.username, body.password)) {
      limiter.recordFailure(clientId, now());
      response.writeHead(401).end();
      return;
    }
    response.writeHead(200).end();
  });
}
export function authenticate(username: string, password: string): boolean {
  return username === "demo" && password === "correct-horse";
}
import assert from "node:assert/strict";
import { test } from "node:test";
import { LoginRateLimiter } from "../src/rateLimit.ts";

test("limits each client to five failed attempts in a rolling minute", () => {
  const limiter = new LoginRateLimiter();
  const startedAt = 1_000;
  for (let attempt = 0; attempt < 5; attempt += 1) {
    assert.equal(limiter.isRateLimited("client-a", startedAt + attempt), false);
    limiter.recordFailure("client-a", startedAt + attempt);
  }
  assert.equal(limiter.isRateLimited("client-a", startedAt + 5), true);
  assert.equal(limiter.isRateLimited("client-b", startedAt + 5), false);
  assert.equal(limiter.isRateLimited("client-a", startedAt + 60_000), false);
});
import assert from "node:assert/strict";
import { once } from "node:events";
import { test } from "node:test";
import { createLoginServer } from "../src/app.ts";

test("the sixth failed HTTP login request returns 429 after five 401 responses", async (context) => {
  const server = createLoginServer();
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  context.after(() => new Promise<void>((resolve, reject) => server.close((error) => error ? reject(error) : resolve())));
  const address = server.address();
  assert.ok(address && typeof address === "object");
  const url = `http://127.0.0.1:${address.port}/login`;
  const sendFailedLogin = () => fetch(url, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ username: "demo", password: "wrong-password" }) });
  for (let attempt = 0; attempt < 5; attempt += 1) assert.equal((await sendFailedLogin()).status, 401);
  assert.equal((await sendFailedLogin()).status, 429);
});
